. $HOME/hadavin-smoke/env.sh; KA=$(awk '$1=="A"{k=$2} END{print k}' $T/keys.txt); KB=$(awk '$1=="B"{k=$2} END{print k}' $T/keys.txt); if [ -z "$KA" ] || [ -z "$KB" ]; then echo "GATE2 key of A or B not in keys.txt: STOP"; elif [ "$KA" = "$KB" ]; then echo "GATE2 A and B have the same key: STOP"; else case "$KA$KB" in *[!A-Za-z0-9_-]*) echo "GATE2 key has an unexpected character: STOP";; *) echo "GATE2 count: $(pgq -U smk_count -d postgres -c "SELECT count(*) FROM mf_leads WHERE lead_key IN ('$KA','$KB')" | tee $T/gate2.out | head -n 1)";; esac; fi
